// Basit @minecraft/server taklidi (test için). Yalnızca eklentinin kullandığı API'ler.
export const GameMode = { Adventure: "Adventure", Creative: "Creative", Spectator: "Spectator", Survival: "Survival" };
export const EquipmentSlot = { Mainhand: "Mainhand", Offhand: "Offhand", Head: "Head", Chest: "Chest", Legs: "Legs", Feet: "Feet" };

const key = (p) => `${Math.floor(p.x)},${Math.floor(p.y)},${Math.floor(p.z)}`;
const MAX1 = (id) => /kabuk_(migferi|zirhi|pantolonu|botu)_|sayfa_ileri|sayfa_geri|kilitli_yuva/.test(id) ? 1 : /_pickaxe|_shovel|_axe|_hoe|_sword|robot_|task_remote|robot_radio|robot_tracker|command_rod|zone_selector|tuning_gear|bucket|kapali_|tamir_kiti|_zirh$|_migfer$|_pantolon$|_bot$|_helmet|_chestplate|_leggings|_boots/.test(id) ? 1 : (/snowball|ender_pearl|egg|_chest|chest_|buyu_/.test(id) ? 16 : 64);

const BARKDUR = (id) => { const m = id.match(/kabuk_(migferi|zirhi|pantolonu|botu)_/); return m ? { migferi: 40, zirhi: 60, pantolonu: 55, botu: 45 }[m[1]] : undefined; };
export const ItemTypes = { _extra: new Set(), get(id) { return ItemTypes._extra.has(id) ? { id } : undefined; }, getAll() { return []; } };

// ------------------------------------------------------------------ parçacık değişkenleri
const fin = (x) => typeof x === "number" && Number.isFinite(x);
export class MolangVariableMap {
  constructor() { this.v = {}; }
  _name(n) { if (typeof n !== "string" || !n.startsWith("variable.")) throw new Error("Molang adı 'variable.' ile başlamalı: " + n); }
  setFloat(n, x) { this._name(n); if (!fin(x)) throw new Error("Molang sayısı geçersiz: " + n + "=" + x); this.v[n] = x; }
  setVector3(n, a) { this._name(n); if (!a || !fin(a.x) || !fin(a.y) || !fin(a.z)) throw new Error("Molang vektörü geçersiz: " + n); this.v[n] = { x: a.x, y: a.y, z: a.z }; }
  setColorRGB(n, c) { this._name(n); this.v[n] = { ...c }; }
  setColorRGBA(n, c) { this._name(n); this.v[n] = { ...c }; }
  setSpeedAndDirection(n, s, d) { this._name(n); this.v[n] = { speed: s, ...d }; }
}
// eklentinin özel parçacıklarının beklediği değişkenler (gen/efekt.py PARTICLE_VARS ile aynı)
const PVARS = {
  "aqualit:simsek": ["yon", "uzun", "kalin", "omur"], "aqualit:zincir": ["yon", "uzun", "omur"],
  "aqualit:sok_dalgasi": ["boy"], "aqualit:enerji_halka": ["boy"], "aqualit:parlama": ["boy"],
  "aqualit:kivilcim": [], "aqualit:kubbe_parilti": [], "aqualit:golge_duman": [], "aqualit:su_topu": [], "aqualit:su_sicrama": [],
};
export const __particles = { log: [], perTick: new Map(), max: 0 };
function recordParticle(name, loc, vars) {
  if (!loc || !fin(loc.x) || !fin(loc.y) || !fin(loc.z)) throw new Error("parçacık konumu geçersiz: " + name);
  if (name.startsWith("aqualit:")) {
    const need = PVARS[name];
    if (!need) throw new Error("bilinmeyen eklenti parçacığı: " + name);
    for (const k of need) {
      const v = vars?.v?.["variable." + k];
      if (v === undefined) throw new Error(`${name}: variable.${k} verilmedi`);
      if (k === "yon" && Math.abs(Math.hypot(v.x, v.y, v.z) - 1) > 0.01) throw new Error(`${name}: yön birim vektör değil`);
      if ((k === "uzun" || k === "omur" || k === "kalin" || k === "boy") && !(v > 0)) throw new Error(`${name}: ${k} pozitif olmalı (${v})`);
    }
  }
  const t = system.currentTick;
  const n = (__particles.perTick.get(t) ?? 0) + 1;
  __particles.perTick.set(t, n);
  if (n > __particles.max) __particles.max = n;
  __particles.log.push({ name, loc: { ...loc }, vars: vars?.v ? { ...vars.v } : undefined, tick: t });
  if (__particles.log.length > 200000) __particles.log.splice(0, 100000);
}

// ------------------------------------------------------------------ zamanlayıcı
class SystemImpl {
  constructor() {
    this.currentTick = 0;
    this.tasks = new Map();
    this.nextId = 1;
    this.beforeEvents = { startup: new Signal() };
    this.afterEvents = { scriptEventReceive: new Signal() };
  }
  run(cb) { return this._add(cb, 1, false); }
  runTimeout(cb, d = 1) { return this._add(cb, Math.max(1, d), false); }
  runInterval(cb, p = 1) { return this._add(cb, Math.max(1, p), true); }
  runJob(gen) { const id = this._add(() => { const r = gen.next(); if (r.done) this.clearRun(id); }, 1, true); return id; }
  clearRun(id) { this.tasks.delete(id); }
  clearJob(id) { this.tasks.delete(id); }
  waitTicks(n) { return new Promise((res) => this.runTimeout(res, n)); }
  _add(cb, delay, repeat) {
    const id = this.nextId++;
    this.tasks.set(id, { cb, at: this.currentTick + delay, period: delay, repeat });
    return id;
  }
  tick() {
    this.currentTick++;
    for (const [id, t] of [...this.tasks]) {
      if (!this.tasks.has(id) || t.at > this.currentTick) continue;
      if (t.repeat) t.at += t.period;
      else this.tasks.delete(id);
      try { t.cb(); } catch (e) { console.error("GÖREV HATASI", e); throw e; }
    }
  }
}

export class Signal {
  constructor() { this.subs = []; }
  subscribe(fn) { this.subs.push(fn); return fn; }
  unsubscribe(fn) { this.subs = this.subs.filter((f) => f !== fn); }
  fire(ev) { for (const f of this.subs) f(ev); return ev; }
}

export const system = new SystemImpl();

// ------------------------------------------------------------------ eşya
export class ItemStack {
  constructor(type, amount = 1) {
    this.typeId = typeof type === "string" ? (type.includes(":") ? type : "minecraft:" + type) : type.id;
    this.amount = amount;
    this.maxAmount = MAX1(this.typeId);
    this.nameTag = undefined;
    this._dp = {};
    this._lore = [];
    this._dur = { damage: 0, maxDurability: this.typeId.includes("tamir_kiti") ? 5 : BARKDUR(this.typeId) ?? 1400, unbreakable: false };
    this.type = { id: this.typeId };
    if (amount > this.maxAmount || amount < 1) throw new Error(`geçersiz adet ${amount} ${this.typeId}`);
  }
  get isStackable() { return this.maxAmount > 1; }
  get localizationKey() { return `item.${this.typeId.split(":")[1]}.name`; }
  clone() { const c = new ItemStack(this.typeId, this.amount); c.nameTag = this.nameTag; c._dp = { ...this._dp }; c._lore = [...this._lore]; c._dur = { ...this._dur }; return c; }
  isStackableWith(o) { return o && o.typeId === this.typeId && this.maxAmount > 1 && JSON.stringify(o._dp) === JSON.stringify(this._dp) && JSON.stringify(o._lore) === JSON.stringify(this._lore); }
  getDynamicProperty(k) { return this._dp[k]; }
  setDynamicProperty(k, v) { if (this.maxAmount > 1) throw new Error("yığılabilir eşyaya dinamik özellik konmaz"); if (v === undefined) delete this._dp[k]; else this._dp[k] = v; }
  setLore(l) {
    l = l ?? [];
    if (l.length > 20) throw new Error("açıklama 20 satırdan uzun");
    for (const x of l) if (x.length > 50) throw new Error("açıklama satırı 50 karakterden uzun: " + x);
    this._lore = [...l];
  }
  getLore() { return [...this._lore]; }
  getComponent(c) { if (c === "minecraft:durability") return this._dur; if (c === "minecraft:enchantable") return { getEnchantment: () => undefined }; return undefined; }
  hasTag(t) { return (t === "minecraft:is_axe" && /_axe$/.test(this.typeId)) || (t === "minecraft:is_pickaxe" && /_pickaxe$/.test(this.typeId)); }
  getTags() { return []; }
}

export class Container {
  constructor(size) { this.size = size; this.slots = new Array(size).fill(undefined); this.isValid = true; }
  get emptySlotsCount() { return this.slots.filter((s) => !s).length; }
  getItem(i) { const s = this.slots[i]; return s ? s.clone() : undefined; }
  setItem(i, it) { this.slots[i] = it ? it.clone() : undefined; }
  addItem(it) {
    let left = it.amount;
    for (let i = 0; i < this.size && left > 0; i++) {
      const s = this.slots[i];
      if (s && s.isStackableWith(it) && s.amount < s.maxAmount) {
        const add = Math.min(left, s.maxAmount - s.amount);
        s.amount += add;
        left -= add;
      }
    }
    for (let i = 0; i < this.size && left > 0; i++) {
      if (!this.slots[i]) {
        const n = Math.min(left, it.maxAmount);
        const c = it.clone();
        c.amount = n;
        this.slots[i] = c;
        left -= n;
      }
    }
    if (left > 0) { const r = it.clone(); r.amount = left; return r; }
    return undefined;
  }
  firstEmptySlot() { const i = this.slots.findIndex((s) => !s); return i < 0 ? undefined : i; }
  swapItems(a, b, other) {
    if (a < 0 || a >= this.size || b < 0 || b >= other.size) throw new Error(`swapItems yuva dışı ${a} ${b}`);
    const x = this.slots[a]; this.slots[a] = other.slots[b]; other.slots[b] = x;
  }
  moveItem(a, b, other) {
    if (a < 0 || a >= this.size || b < 0 || b >= other.size) throw new Error(`moveItem yuva dışı ${a} ${b}`);
    const x = this.slots[a];
    if (!x) return;
    const y = other.slots[b];
    if (!y) { other.slots[b] = x; this.slots[a] = undefined; return; }
    if (y.isStackableWith(x)) {
      const n = Math.min(x.amount, y.maxAmount - y.amount);
      y.amount += n; x.amount -= n;
      if (x.amount <= 0) this.slots[a] = undefined;
    }
  }
  transferItem(a, other) {
    const x = this.slots[a];
    if (!x) return undefined;
    this.slots[a] = undefined;
    const rest = other.addItem(x);
    if (rest) this.slots[a] = rest;
    return rest;
  }
  total(id) { return this.slots.reduce((n, s) => n + (s && s.typeId === id ? s.amount : 0), 0); }
}

// ------------------------------------------------------------------ bloklar
export class BlockPermutation {
  constructor(id, states = {}) { this.type = { id }; this._states = { ...states }; }
  static resolve(id, states = {}) { return new BlockPermutation(id.includes(":") ? id : "minecraft:" + id, states); }
  getState(n) { return this._states[n]; }
  getAllStates() { return { ...this._states }; }
  withState(n, v) { return new BlockPermutation(this.type.id, { ...this._states, [n]: v }); }
  matches(id) { return this.type.id === id; }
  getItemStack(n = 1) {
    const id = this.type.id;
    if (/air|water|lava|fire/.test(id)) return undefined;
    return new ItemStack(id, n);
  }
  hasTag() { return false; }
  getTags() { return []; }
}

export class BlockVolume {
  constructor(from, to) { this.from = from; this.to = to; }
  getBlockLocationIterator() {
    const a = this.from, b = this.to;
    const out = [];
    for (let x = Math.min(a.x, b.x); x <= Math.max(a.x, b.x); x++)
      for (let y = Math.min(a.y, b.y); y <= Math.max(a.y, b.y); y++)
        for (let z = Math.min(a.z, b.z); z <= Math.max(a.z, b.z); z++) out.push({ x, y, z });
    return out[Symbol.iterator]();
  }
}

class Block {
  constructor(dim, p) { this.dimension = dim; this.x = p.x; this.y = p.y; this.z = p.z; this.location = { x: p.x, y: p.y, z: p.z }; }
  get _cell() { return this.dimension._cell(this); }
  get typeId() { return this._cell.type; }
  get permutation() { const c = this._cell; return new BlockPermutation(c.type, c.states); }
  get type() { return { id: this.typeId }; }
  get isAir() { return this.typeId === "minecraft:air"; }
  get isLiquid() { return /water|lava/.test(this.typeId); }
  get isValid() { return true; }
  setType(t) { this.dimension.setBlockType(this, t); }
  setPermutation(p) { this.dimension.setBlockPermutation(this, p); }
  above(n = 1) { return this.dimension.getBlock({ x: this.x, y: this.y + n, z: this.z }); }
  below(n = 1) { return this.dimension.getBlock({ x: this.x, y: this.y - n, z: this.z }); }
  center() { return { x: this.x + 0.5, y: this.y + 0.5, z: this.z + 0.5 }; }
  bottomCenter() { return { x: this.x + 0.5, y: this.y, z: this.z + 0.5 }; }
  getComponent(c) {
    if (c === "minecraft:inventory" && /furnace|smoker/.test(this.typeId)) return { container: this.dimension._furnace(this) };
    if (c === "minecraft:inventory" && /^minecraft:(chest|trapped_chest|barrel)$/.test(this.typeId)) return { container: this.dimension._chest(this) };
    if (c === "minecraft:dynamic_properties" && this.typeId.startsWith("aqualit:")) {
      const cell = this.dimension._ensure(this);
      cell.dp ??= {};
      return { get: (k) => cell.dp[k], set: (k, v) => { if (v === undefined) delete cell.dp[k]; else cell.dp[k] = v; } };
    }
    return undefined;
  }
  hasTag() { return false; }
  getTags() { return []; }
}

// ------------------------------------------------------------------ boyut
class Dimension {
  constructor(id, terrain) {
    this.id = id;
    this.heightRange = { min: -64, max: 320 };
    this.cells = new Map();
    this.terrain = terrain;
    this.furnaces = new Map();
    this.sounds = [];
  }
  _cell(p) {
    const k = key(p);
    let c = this.cells.get(k);
    if (!c) c = { type: this.terrain(Math.floor(p.x), Math.floor(p.y), Math.floor(p.z)), states: {} };
    return c;
  }
  _ensure(p) {
    const k = key(p);
    let c = this.cells.get(k);
    if (!c) {
      c = { type: this.terrain(Math.floor(p.x), Math.floor(p.y), Math.floor(p.z)), states: {} };
      this.cells.set(k, c);
    }
    return c;
  }
  _chest(p) {
    const k = key(p);
    this.chests ??= new Map();
    if (!this.chests.has(k)) this.chests.set(k, new Container(27));
    return this.chests.get(k);
  }
  _furnace(p) {
    const k = key(p);
    if (!this.furnaces.has(k)) this.furnaces.set(k, new Container(3));
    return this.furnaces.get(k);
  }
  getBlock(p) {
    if (p.y < this.heightRange.min || p.y >= this.heightRange.max) return undefined;
    return new Block(this, { x: Math.floor(p.x), y: Math.floor(p.y), z: Math.floor(p.z) });
  }
  setBlockType(p, t) {
    const id = typeof t === "string" ? (t.includes(":") ? t : "minecraft:" + t) : t.id;
    this._dropContainer(p, id);
    this.cells.set(key(p), { type: id, states: {} });
  }
  _dropContainer(p, newType) {
    const k = key(p);
    if (!this.chests?.has(k) || /^minecraft:(chest|trapped_chest|barrel)$/.test(newType)) return;
    const c = this.chests.get(k);
    this.chests.delete(k);
    // çift sandığın öbür yarısı tekli olur (oyundaki gibi: eşyaları kendi yarısında kalır)
    if (c.size === 54 && c._pair) {
      const other = c._pair.find((q) => key(q) !== k);
      if (other && this.chests.get(key(other)) === c) this.chests.set(key(other), new Container(27));
    }
  }
  setBlockPermutation(p, perm) {
    this._dropContainer(p, perm.type.id);
    const old = this.cells.get(key(p));
    const cell = { type: perm.type.id, states: { ...perm._states } };
    if (old && old.type === cell.type && old.dp) cell.dp = old.dp; // aynı blok: blok varlığı korunur
    this.cells.set(key(p), cell);
  }
  getBlocks(vol, opts) {
    const inc = new Set(opts.includeTypes ?? []);
    const list = [];
    for (const it = vol.getBlockLocationIterator(), r = { done: false }; ;) {
      const n = it.next();
      if (n.done) break;
      const p = n.value;
      if (!inc.size || inc.has(this._cell(p).type)) list.push(p);
    }
    return { getBlockLocationIterator: () => list[Symbol.iterator]() };
  }
  getTopmostBlock({ x, z }) {
    for (let y = 200; y > -64; y--) if (this._cell({ x, y, z }).type !== "minecraft:air") return this.getBlock({ x, y, z });
    return undefined;
  }
  spawnEntity(id, loc, opts = {}) {
    if (!loc || !fin(loc.x) || !fin(loc.y) || !fin(loc.z)) throw new Error("varlık konumu geçersiz: " + id);
    const e = new Entity(id, this, { ...loc }, opts);
    if (opts.spawnEvent) {
      const m = /^aqualit:as_(.+)$/.exec(opts.spawnEvent);
      if (id === "aqualit:fx") {
        if (!m || !["kubbe", "hayalet"].includes(m[1])) throw new Error("geçersiz efekt olayı " + opts.spawnEvent);
        e._props["aqualit:fx"] = m[1];
      }
      e._events.push(opts.spawnEvent);
    }
    W.entities.push(e);
    return e;
  }
  spawnItem(stack, loc) {
    const e = new Entity("minecraft:item", this, { ...loc });
    e._item = stack.clone();
    W.entities.push(e);
    return e;
  }
  getEntities(q = {}) {
    return W.entities.filter((e) => e.isValid && e.dimension === this && (!q.type || e.typeId === q.type)
      && (!q.families || q.families.every((f) => (e._families ?? []).includes(f)))
      && (!q.location || !q.maxDistance || dist(e.location, q.location) <= q.maxDistance));
  }
  getEntitiesAtBlockLocation(p) { return W.entities.filter((e) => e.isValid && e.dimension === this && key(e.location) === key(p)); }
  getPlayers(q = {}) { return this.getEntities(q).filter((e) => e instanceof Player); }
  playSound(id, loc) { this.sounds.push(id); }
  spawnParticle(name, loc, vars) { recordParticle(name, loc, vars); }
  runCommand(cmd) {
    const m = /^setblock (-?\d+) (-?\d+) (-?\d+) (\S+)/.exec(cmd);
    if (m) this.setBlockType({ x: +m[1], y: +m[2], z: +m[3] }, m[4]);
    (this.cmds ??= []).push(cmd);
    return { successCount: 1 };
  }
  isChunkLoaded(p) { return this.unloaded ? !this.unloaded(p) : true; }
  getBiome(p) { return { id: this.biome ? this.biome(Math.floor(p.x), Math.floor(p.z)) : "minecraft:plains" }; }
  calculateClosestBiomeFromSeed(pos, biome, opts = {}) {
    const id = typeof biome === "string" ? biome : biome.id;
    const R = Math.min(4000, Math.floor((opts.boundingSize?.x ?? 1600) / 2));
    if (this.getBiome(pos).id === id) return { x: Math.floor(pos.x), y: 64, z: Math.floor(pos.z) };
    for (let r = 16; r <= R; r += 16) {
      for (let a = 0; a < 64; a++) {
        const x = Math.floor(pos.x + Math.cos(a * Math.PI / 32) * r), z = Math.floor(pos.z + Math.sin(a * Math.PI / 32) * r);
        if (this.getBiome({ x, z }).id === id) return { x, y: 64, z };
      }
    }
    return undefined;
  }
}

const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);

// ------------------------------------------------------------------ varlıklar
let EID = 1;
export class Entity {
  constructor(typeId, dim, loc, opts = {}) {
    this.typeId = typeId;
    this.id = String(-(EID++));
    this.dimension = dim;
    this.location = loc;
    this._rot = { x: 0, y: opts.initialRotation ?? 0 };
    this._props = {};
    this._dp = {};
    this._valid = true;
    this.nameTag = "";
    this._events = [];
    this._effects = {};
    this.isSneaking = false;
    this.isSprinting = false;
    this.isInWater = false;
    this._vel = { x: 0, y: 0, z: 0 };
    this._kb = [];
    this._families = /zombie|skeleton|creeper|spider/.test(typeId) ? ["monster", "mob"] : [];
    if (typeId === "aqualit:robot") {
      this._props = { "aqualit:type": "madenci", "aqualit:model": 1, "aqualit:move": "none", "aqualit:act": "none", "aqualit:act2": "none" };
      this._inv = new Container(27);
      this._hand = undefined;
    }
    if (typeId === "aqualit:fx") this._props = { "aqualit:fx": "kubbe", "aqualit:boy": 1 };
    if (typeId === "aqualit:kesif") { this._props = { "aqualit:form": "robot", "aqualit:gecis": false, "aqualit:egim": 0 }; this._riders = []; }
    this.isOnGround = true;
    if (typeId === "aqualit:robot_chest") {
      this._props = { "aqualit:kind": "genel", "aqualit:open": false };
      this._inv = new Container(27);
    }
    if (typeId === "aqualit:sandik_depo") {
      this._props = { "aqualit:kind": "genel" };
      this._inv = new Container(128);
    }
    if (typeId === "aqualit:sandik_ek") this._inv = new Container(128);
  }
  get isValid() { return this._valid; }
  remove() { this._valid = false; }
  kill() { this._valid = false; return true; }
  teleport(loc, opts = {}) {
    if (!Number.isFinite(loc.x) || !Number.isFinite(loc.y) || !Number.isFinite(loc.z)) throw new Error("geçersiz konum");
    this.location = { ...loc };
    if (opts.rotation) this._rot = { ...opts.rotation };
    W.teleports++;
  }
  tryTeleport(loc, o) { this.teleport(loc, o); return true; }
  setRotation(r) { this._rot = { ...r }; }
  getRotation() { return { ...this._rot }; }
  getProperty(k) { return this._props[k]; }
  setProperty(k, v) {
    if (this.typeId === "aqualit:robot" && k === "aqualit:act") {
      const ok = ["none", "mine", "dig", "chop", "hoe", "place", "carry", "sit", "wave", "celebrate", "attack", "sleep", "think", "look", "boot"];
      if (!ok.includes(v)) throw new Error("geçersiz act " + v);
    }
    if (this.typeId === "aqualit:robot" && k === "aqualit:act2") {
      const ok = ["none", "p_hook", "p_sword", "p_dash", "p_dome", "p_thunder", "water_throw", "water_catch", "water_pour", "kit",
        "fly", "hat_off", "hat_hold", "hat_on", "tutun"];
      if (!ok.includes(v)) throw new Error("geçersiz act2 " + v);
    }
    if (this.typeId === "aqualit:robot" && k === "aqualit:move" && !["none", "walk", "run", "climb", "swim"].includes(v)) throw new Error("geçersiz move " + v);
    if (this.typeId === "aqualit:kesif" && k === "aqualit:form" && !["robot", "ucak", "gemi", "denizalti", "arazi", "matkap"].includes(v)) throw new Error("geçersiz biçim " + v);
    if (this.typeId === "aqualit:kesif" && k === "aqualit:egim" && !(fin(v) && v >= -90 && v <= 90)) throw new Error("geçersiz eğim " + v);
    if (this.typeId === "aqualit:fx" && k === "aqualit:boy" && !(fin(v) && v >= 0 && v <= 4)) throw new Error("geçersiz boy " + v);
    if (this.typeId === "aqualit:fx" && k === "aqualit:fx" && !["kubbe", "hayalet"].includes(v)) throw new Error("geçersiz efekt " + v);
    if (this.typeId === "aqualit:dron" && k === "aqualit:dact" && !["none", "place", "out", "in"].includes(v)) throw new Error("geçersiz dron hareketi " + v);
    if (this.typeId === "aqualit:robot" && k === "aqualit:type"
      && !["madenci", "kurekci", "ciftci", "oduncu", "kilicli", "insaatci", "toplayici"].includes(v)) throw new Error("geçersiz robot türü " + v);
    if (this.typeId === "aqualit:sandik_depo" && k === "aqualit:kind"
      && !["genel", "madenci", "kurekci", "ciftci", "oduncu", "kilicli", "insaatci", "toplayici"].includes(v)) throw new Error("geçersiz sandık türü " + v);
    this._props[k] = v;
  }
  getDynamicProperty(k) { return this._dp[k]; }
  setDynamicProperty(k, v) {
    if (v === undefined) delete this._dp[k];
    else {
      if (typeof v === "string" && v.length > 32767) throw new Error("dinamik özellik çok uzun: " + k);
      this._dp[k] = v;
    }
  }
  getDynamicPropertyIds() { return Object.keys(this._dp); }
  triggerEvent(e) {
    this._events.push(e);
    const m = /^aqualit:form_(\w+)$/.exec(e);
    if (m && this.typeId === "aqualit:kesif") {
      this._props["aqualit:form"] = m[1];
      // bileşen grubu değişince binenler iner (gerçek oyunda da; kesif.js yeniden bindirir)
      for (const r of this._riders) r._ridingOn = undefined;
      this._riders = [];
    }
  }
  get isInWater() { return this._inWater ?? /water/.test(this.dimension._cell(this.location).type); }
  set isInWater(v) { this._inWater = v; }
  getViewDirection() {
    const y = (this._rot.y * Math.PI) / 180, x = (this._rot.x * Math.PI) / 180;
    return { x: -Math.sin(y) * Math.cos(x), y: -Math.sin(x), z: Math.cos(y) * Math.cos(x) };
  }
  getComponent(c) {
    if (c === "minecraft:inventory" && this._inv) return { container: this._inv };
    if (c === "minecraft:item" && this._item) return { itemStack: this._item };
    if (c === "minecraft:rideable" && this.typeId === "aqualit:kesif" && this._props["aqualit:form"] !== "robot") {
      const self = this;
      return {
        getRiders: () => self._riders.filter((r) => r.isValid),
        addRider: (r) => {
          const f = self._props["aqualit:form"];
          if (self._riders.length >= ({ ucak: 10, gemi: 10, denizalti: 1, arazi: 10, matkap: 10 }[f] ?? 5) || self._riders.includes(r)) return false;
          if (f === "denizalti" && r.typeId !== "minecraft:player") return false;    // denizaltı: yalnız oyuncu (family_types)
          self._riders.push(r); r._ridingOn = self; return true;
        },
        ejectRider: (r) => { self._riders = self._riders.filter((x) => x !== r); r._ridingOn = undefined; },
        ejectRiders: () => { for (const r of self._riders) r._ridingOn = undefined; self._riders = []; },
      };
    }
    if (c === "minecraft:riding" && this._ridingOn) return { entityRidingOn: this._ridingOn };
    if (c === "minecraft:equippable") {
      const self = this;
      return {
        getEquipment: (s) => (s === "Mainhand" ? self._hand : undefined),
        setEquipment: (s, it) => { if (s === "Mainhand") self._hand = it; return true; },
      };
    }
    if (c === "minecraft:tameable") return { tame: (p) => { this._owner = p.id; return true; }, isTamed: !!this._owner };
    if (c === "minecraft:health") {
      this._hp ??= { currentValue: 20, effectiveMax: 20 };
      const h = this._hp;
      return {
        get currentValue() { return h.currentValue; },
        get effectiveMax() { return h.effectiveMax; },
        resetToMaxValue() { h.currentValue = h.effectiveMax; },
        setCurrentValue(v) { h.currentValue = v; return true; },
      };
    }
    return undefined;
  }
  hasComponent(c) { return !!this.getComponent(c); }
  runCommand(cmd) { W.commands.push(cmd); return { successCount: 1 }; }
  addEffect(t, d, o) { this._effects[t] = { duration: d, amplifier: o?.amplifier ?? 0 }; return this._effects[t]; }
  removeEffect(t) { delete this._effects[t]; return true; }
  getEffect(t) { return this._effects[t]; }
  applyImpulse(v) {
    if (!v || !fin(v.x) || !fin(v.y) || !fin(v.z)) throw new Error("geçersiz itki");
    this._vel = { x: this._vel.x + v.x, y: this._vel.y + v.y, z: this._vel.z + v.z };
  }
  clearVelocity() { this._vel = { x: 0, y: 0, z: 0 }; }
  getVelocity() { return { ...this._vel }; }
  applyKnockback(h, v) { this._kb.push({ h, v }); }
  applyDamage(n, o) { this._damage = (this._damage ?? 0) + n; return true; }
  getHeadLocation() { return { x: this.location.x, y: this.location.y + 1.6, z: this.location.z }; }
  getEntitiesFromViewDirection() { return []; }
}

export class Waypoint {
  constructor(sel, color) { this.textureSelector = sel; this.color = color; this.isValid = true; this.isEnabled = true; }
  remove() { this.isValid = false; }
  getDimensionLocation() { return this._dl; }
}
export class EntityWaypoint extends Waypoint {
  constructor(entity, sel, rules, color) { super(sel, color); this.entity = entity; this.entityRules = rules; }
  getDimensionLocation() { return { dimension: this.entity.dimension, ...this.entity.location }; }
}
export class LocationWaypoint extends Waypoint {
  constructor(dl, sel, color) { super(sel, color); this._dl = dl; }
  setDimensionLocation(dl) { this._dl = dl; }
}
class LocatorBarMock {
  constructor() { this.list = []; this.maxCount = 32; }
  get count() { return this.list.length; }
  addWaypoint(w) { if (this.list.length >= this.maxCount) throw new Error("dolu"); this.list.push(w); }
  removeWaypoint(w) { this.list = this.list.filter((x) => x !== w); }
  hasWaypoint(w) { return this.list.includes(w); }
  getAllWaypoints() { return [...this.list]; }
  removeAllWaypoints() { this.list = []; }
}

export class Player extends Entity {
  constructor(name, dim, loc) {
    super("minecraft:player", dim, loc);
    this.name = name;
    this.locatorBar = new LocatorBarMock();
    this.id = "P" + name;
    this.messages = [];
    this.actionbar = [];
    this._inv = new Container(36);
    this.selectedSlotIndex = 0;
    this.gameMode = "Survival";
    this.onScreenDisplay = { setActionBar: (t) => this.actionbar.push(String(t)), setTitle() {} };
    const cam = (this._cam = { fades: [], shakes: [] });
    this.camera = {
      setCamera() {}, clear() {}, attachToEntity() {},
      fade(o) {
        const t = o?.fadeTime;
        if (t && !(fin(t.fadeInTime) && fin(t.holdTime) && fin(t.fadeOutTime))) throw new Error("fade süreleri eksik");
        cam.fades.push(o);
      },
      addShake(o) {
        if (!o || !fin(o.intensity) || !fin(o.duration) || !["Positional", "Rotational"].includes(o.type)) throw new Error("sarsıntı ayarı geçersiz");
        cam.shakes.push(o);
      },
      stopShaking() {},
    };
    this._mv = { x: 0, y: 0 };
    this.inputInfo = { getButtonState: () => "Released", getMovementVector: () => ({ ...this._mv }) };
  }
  sendMessage(m) { this.messages.push(String(m)); }
  playSound() {}
  getGameMode() { return this.gameMode; }
  spawnParticle() {}
  getComponent(c) {
    if (c === "minecraft:inventory") return { container: this._inv };
    if (c === "minecraft:cursor_inventory") {
      const self = this;
      return { get item() { return self._cursor ? self._cursor.clone() : undefined; }, clear() { self._cursor = undefined; } };
    }
    if (c === "minecraft:equippable") {
      const self = this;
      self._eq ??= {};
      return {
        getEquipment: (s) => (s === "Mainhand" ? self._inv.getItem(self.selectedSlotIndex) : (self._eq[s] ? self._eq[s].clone() : undefined)),
        setEquipment: (s, it) => {
          if (s === "Mainhand") self._inv.setItem(self.selectedSlotIndex, it);
          else self._eq[s] = it ? it.clone() : undefined;
          return true;
        },
      };
    }
    if (c === "minecraft:movement" || c === "minecraft:underwater_movement") {
      this._attr ??= {};
      const def = c === "minecraft:movement" ? 0.1 : 0.02;
      const a = (this._attr[c] ??= { defaultValue: def, currentValue: def });
      return {
        get defaultValue() { return a.defaultValue; },
        get currentValue() { return a.currentValue; },
        setCurrentValue(v) { a.currentValue = v; return true; },
        resetToDefaultValue() { a.currentValue = a.defaultValue; },
      };
    }
    if (c === "minecraft:health") {
      this._hp ??= { currentValue: 20, effectiveMax: 20 };
      const h = this._hp;
      return { get currentValue() { return h.currentValue; }, get effectiveMax() { return h.effectiveMax; },
        resetToMaxValue() { h.currentValue = h.effectiveMax; }, setCurrentValue(v) { h.currentValue = v; return true; } };
    }
    return super.getComponent(c);
  }
}

// ------------------------------------------------------------------ dünya
class WorldImpl {
  constructor() {
    this.dims = {};
    this.entities = [];
    this._dp = {};
    this.teleports = 0;
    this.commands = [];
    const sig = () => new Signal();
    this.afterEvents = new Proxy({}, { get: (o, k) => (o[k] ??= sig()) });
    this.beforeEvents = new Proxy({}, { get: (o, k) => (o[k] ??= sig()) });
  }
  getDimension(id) {
    const k = id.replace("minecraft:", "");
    return this.dims[k] ?? this.dims.overworld;
  }
  getPlayers() { return this.entities.filter((e) => e instanceof Player && e.isValid); }
  getAllPlayers() { return this.getPlayers(); }
  getEntity(id) { return this.entities.find((e) => e.id === id && e.isValid); }
  getDynamicProperty(k) { return this._dp[k]; }
  setDynamicProperty(k, v) {
    if (v === undefined) delete this._dp[k];
    else {
      if (typeof v === "string" && v.length > 32767) throw new Error("dünya özelliği çok uzun: " + k);
      this._dp[k] = v;
    }
  }
  getDynamicPropertyIds() { return Object.keys(this._dp); }
}

export const world = new WorldImpl();
const W = world;
// ganimet tabloları (yalnız deneme odası kasası)
world.getLootTableManager = () => ({
  getLootTable(path) { return /trial_chambers\/reward|archaeology\//.test(path) ? { path } : undefined; },
  generateLootFromTable(t) {
    if (/archaeology/.test(t.path)) return [new ItemStack("minecraft:archer_pottery_sherd", 1)];
    return /ominous/.test(t.path) ? [new ItemStack("minecraft:heavy_core", 1)] : [new ItemStack("minecraft:diamond", 2), new ItemStack("minecraft:emerald", 3)];
  },
});
// işleme alanları (en çok 10)
world.tickingAreaManager = {
  areas: new Map(), maxChunkCount: 1000,
  hasCapacity() { return this.areas.size < 10; },
  createTickingArea(id, o) {
    if (!o?.dimension || !o.from || !o.to) throw new Error("işleme alanı ayarı eksik");
    if (this.areas.size >= 10 && !this.areas.has(id)) return Promise.reject(new Error("işleme alanı kotası dolu"));
    const a = { identifier: id, dimension: o.dimension, boundingBox: { min: o.from, max: o.to }, isFullyLoaded: true };
    this.areas.set(id, a);
    return Promise.resolve(a);
  },
  removeTickingArea(id) { return this.areas.delete(typeof id === "string" ? id : id.identifier); },
  hasTickingArea(id) { return this.areas.has(id); },
  getTickingArea(id) { return this.areas.get(id); },
  getAllTickingAreas() { return [...this.areas.values()]; },
  removeAllTickingAreas() { this.areas.clear(); },
};
// basit fizik: Keşif hızıyla ilerler, yolcular onunla taşınır (gerçek oyunda motor yapar)
system.runInterval(() => {
  for (const e of W.entities) {
    if (e.typeId !== "aqualit:kesif" || !e._valid || !e._fizik) continue;   // yalnız fizik açılan Keşif (eski denemeler hızı ölçer)
    const v = e._vel;
    if (v.x || v.y || v.z) e.location = { x: e.location.x + v.x, y: e.location.y + v.y, z: e.location.z + v.z };
    for (const r of e._riders ?? []) r.location = { x: e.location.x, y: e.location.y + 0.8, z: e.location.z };
  }
}, 1);

/** Test yardımcısı: boyut oluştur. */
export function __makeDimension(id, terrain) {
  const d = new Dimension("minecraft:" + id, terrain);
  world.dims[id] = d;
  return d;
}
export function __pairChests(dim, a, b) {
  const c = new Container(54);
  c._pair = [{ ...a }, { ...b }];
  dim.chests ??= new Map();
  dim.chests.set(key(a), c);
  dim.chests.set(key(b), c);
  return c;
}
export function __makePlayer(name, dim, loc) {
  const p = new Player(name, dim, loc);
  world.entities.push(p);
  return p;
}

// ------------------------------------------------------------------ yapı yöneticisi (Mimar)
// Paketin yapı dosyalarını (out/Aqualit_BP/structures/<ns>/<ad>.mcstructure, küçük-sonlu NBT) okur.
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

function readNbtLE(buf) {
  let o = 0;
  const u8 = () => buf.readUInt8(o++);
  const i16 = () => { const v = buf.readInt16LE(o); o += 2; return v; };
  const i32 = () => { const v = buf.readInt32LE(o); o += 4; return v; };
  const str = () => { const n = buf.readUInt16LE(o); o += 2; const s = buf.toString("utf8", o, o + n); o += n; return s; };
  const pay = (t) => {
    switch (t) {
      case 1: { const v = buf.readInt8(o); o += 1; return v; }
      case 2: return i16();
      case 3: return i32();
      case 4: { const v = buf.readBigInt64LE(o); o += 8; return Number(v); }
      case 5: { const v = buf.readFloatLE(o); o += 4; return v; }
      case 6: { const v = buf.readDoubleLE(o); o += 8; return v; }
      case 7: { const n = i32(); const v = buf.subarray(o, o + n); o += n; return v; }
      case 8: return str();
      case 9: { const et = u8(); const n = i32(); const a = new Array(n); for (let i = 0; i < n; i++) a[i] = pay(et); return a; }
      case 10: { const c = {}; for (;;) { const tt = u8(); if (tt === 0) break; const k = str(); c[k] = pay(tt); c.__t ??= {}; c.__t[k] = tt; } return c; }
      case 11: { const n = i32(); const a = new Array(n); for (let i = 0; i < n; i++) a[i] = i32(); return a; }
      case 12: { const n = i32(); const a = new Array(n); for (let i = 0; i < n; i++) { a[i] = Number(buf.readBigInt64LE(o)); o += 8; } return a; }
      default: throw new Error("NBT etiketi " + t);
    }
  };
  const t = u8(); str();
  return pay(t);
}

class Structure {
  constructor(id, nbt) {
    this.id = id;
    const [x, y, z] = nbt.size;
    this.size = { x, y, z };
    const pal = nbt.structure.palette.default.block_palette.map((p) => {
      const st = {};
      for (const [k, v] of Object.entries(p.states)) {
        if (k === "__t") continue;
        st[k] = p.states.__t[k] === 1 ? !!v : v;
      }
      return BlockPermutation.resolve(p.name, st);
    });
    this._pal = pal;
    this._idx = nbt.structure.block_indices[0];
  }
  get isValid() { return true; }
  getBlockPermutation(p) {
    const { x: W, y: H, z: D } = this.size;
    if (p.x < 0 || p.y < 0 || p.z < 0 || p.x >= W || p.y >= H || p.z >= D) throw new Error("yapı dışı konum");
    const v = this._idx[(p.x * H + p.y) * D + p.z];
    return v >= 0 ? this._pal[v] : undefined;
  }
}

const HERE_MOCK = dirname(fileURLToPath(import.meta.url));
const STRUCT_DIR = process.env.AQUALIT_STRUCT_DIR ?? join(HERE_MOCK, "..", "..", "..", "..", "..", "out", "Aqualit_BP", "structures");
const _structs = new Map();
world.structureManager = {
  get(id) {
    if (_structs.has(id)) return _structs.get(id);
    const [ns, name] = id.split(":");
    const f = join(STRUCT_DIR, ns, name + ".mcstructure");
    const s = existsSync(f) ? new Structure(id, readNbtLE(readFileSync(f))) : undefined;
    _structs.set(id, s);
    return s;
  },
};
